/etc/nftables.conf.content:
#!/usr/sbin/nft -f

table inet filter {
  chain input {
    type filter hook input priority 0; policy drop;

    # Loopback
    iif lo accept

    # Connexions établies
    ct state established,related accept

    # SSH
    tcp dport 22 accept

    # HTTP / HTTPS
    tcp dport { 80, 443 } accept

    # ERREUR : règle de debug oubliée par l'admin
    tcp dport 4444 accept

    # Tout le reste est droppé
  }

  chain output {
    type filter hook output priority 0; policy accept;
  }
}

